package com.adorehairstudio.api.controller;
import com.adorehairstudio.api.dto.*; import com.adorehairstudio.api.repo.AdminUserRepository; import com.adorehairstudio.api.security.JwtService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth")
public class AuthController { private final AdminUserRepository repo; private final PasswordEncoder pe; private final JwtService jwt; public AuthController(AdminUserRepository r,PasswordEncoder p,JwtService j){repo=r;pe=p;jwt=j;} @PostMapping("/login") public ResponseEntity<?> login(@Valid @RequestBody LoginRequest req){return repo.findByEmailIgnoreCase(req.email()).filter(u->pe.matches(req.password(),u.getPasswordHash())).<ResponseEntity<?>>map(u->ResponseEntity.ok(new LoginResponse(jwt.create(u.getEmail()),u.getEmail()))).orElseGet(()->ResponseEntity.status(401).body(java.util.Map.of("message","Invalid email or password")));}}
